import { createRequire } from 'node:module'
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json')
const { chromium } = require('playwright')
const browser = await chromium.launch({ args: ['--use-gl=swiftshader'] })

async function run(name, viewport, mobile = true) {
  const context = await browser.newContext({
    viewport, screen: viewport, isMobile: mobile, hasTouch: true, deviceScaleFactor: 2,
  })
  const page = await context.newPage()
  const errors = []
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()) })
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message))
  await page.goto('http://localhost:3002/', { waitUntil: 'load' })
  await page.evaluate(() => localStorage.clear())
  await page.reload({ waitUntil: 'load' })
  await page.waitForTimeout(500)
  const info = () => page.evaluate(() => {
    const A = window.__NEON_APEX__
    const el = (id) => { const r = document.getElementById(id).getBoundingClientRect(); return { x: +r.x.toFixed(1), y: +r.y.toFixed(1), w: +r.width.toFixed(1), h: +r.height.toFixed(1), display: getComputedStyle(document.getElementById(id)).display } }
    return { screen: A.game.screen, body: document.body.className, frame: el('frame'), deck: el('deck'), sw: getComputedStyle(document.documentElement).getPropertyValue('--sw'), vw: innerWidth, vh: innerHeight, dpr: devicePixelRatio }
  })
  console.log(`\n== ${name} ==`)
  console.log('title', await info())
  await page.screenshot({ path: `/tmp/opencode/m2-${name}-title.png` })
  await page.touchscreen.tap((viewport.width) / 2, (viewport.height) / 2)
  await page.waitForTimeout(400)
  console.log('menu', await info())
  await page.screenshot({ path: `/tmp/opencode/m2-${name}-menu.png` })
  const box = await page.locator('#frame').boundingBox()
  const tapV = async (x, y) => {
    await page.touchscreen.tap(box.x + x * box.width / 384, box.y + y * box.height / 216)
    await page.waitForTimeout(400)
  }
  // menu drift row virtual x100 y100
  await tapV(100, 100)
  await page.waitForTimeout(500)
  console.log('drift', await info())
  await page.screenshot({ path: `/tmp/opencode/m2-${name}-drift.png` })

  // Let countdown finish, then use real touch to hold GAS
  await page.waitForTimeout(3200)
  const gas = await page.locator('[data-act="throttle"]').boundingBox()
  const right = await page.locator('[data-act="right"]').boundingBox()
  const drift = await page.locator('[data-act="drift"]').boundingBox()
  console.log('buttons', { gas, right, drift })
  const center = b => ({ x: b.x + b.width / 2, y: b.y + b.height / 2 })
  const g = center(gas); const r = center(right); const dr = center(drift)
  const cdp = await context.newCDPSession(page)
  // touchStart gas, then add right, then drift
  await cdp.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ ...g, id: 1, radiusX: 4, radiusY: 4, force: 1 }] })
  await page.waitForTimeout(1600)
  await cdp.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ ...g, id: 1, radiusX: 4, radiusY: 4, force: 1 }, { ...r, id: 2, radiusX: 4, radiusY: 4, force: 1 }] })
  await page.waitForTimeout(500)
  await cdp.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ ...g, id: 1, radiusX: 4, radiusY: 4, force: 1 }, { ...r, id: 2, radiusX: 4, radiusY: 4, force: 1 }, { ...dr, id: 3, radiusX: 4, radiusY: 4, force: 1 }] })
  await page.waitForTimeout(600)
  console.log('touch drift state', await page.evaluate(() => {
    const d = window.__NEON_APEX__.game.drift
    return { speed: d.car.speed, slip: d.car.slip, score: d.scoreF, combo: d.combo, walls: d.walls, held: [...document.querySelectorAll('.tbtn.active')].map(b => b.dataset.act) }
  }))
  await page.screenshot({ path: `/tmp/opencode/m2-${name}-drift-touch.png` })
  // release right and drift, keep gas
  await cdp.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [{ ...g, id: 1, radiusX: 4, radiusY: 4, force: 1 }] })
  await page.waitForTimeout(400)
  console.log('after multi release', await page.evaluate(() => {
    const d = window.__NEON_APEX__.game.drift
    return { speed: d.car.speed, slip: d.car.slip, held: [...document.querySelectorAll('.tbtn.active')].map(b => b.dataset.act) }
  }))
  await page.screenshot({ path: `/tmp/opencode/m2-${name}-drift-release.png` })
  await cdp.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] })
  await page.waitForTimeout(400)
  console.log('all released', await page.evaluate(() => ({ held: [...document.querySelectorAll('.tbtn.active')].map(b => b.dataset.act) })))
  // force finish
  await page.evaluate(() => { const d = window.__NEON_APEX__.game.drift; if (d) d.timer = 0.05 })
  await page.waitForTimeout(500)
  await page.screenshot({ path: `/tmp/opencode/m2-${name}-result.png` })
  console.log('result', await page.evaluate(() => {
    const A = window.__NEON_APEX__
    return { screen: A.game.screen, hits: A.game.hits.map(h => h.id), result: A.game.drift?.result }
  }))
  console.log('errors', errors)
  await context.close()
}

await run('portrait', { width: 390, height: 844 }, true)
await run('landscape', { width: 844, height: 390 }, true)
await run('android', { width: 360, height: 800 }, true)
await run('tablet', { width: 768, height: 1024 }, true)
await browser.close()

