import { createRequire } from 'node:module'
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json')
const { chromium } = require('playwright')
const browser = await chromium.launch({ args: ['--use-gl=swiftshader'] })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
const errors = []
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()) })
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message))
await page.goto('http://localhost:3002/', { waitUntil: 'load' })
await page.evaluate(() => localStorage.clear())
await page.reload({ waitUntil: 'load' })
await page.waitForTimeout(300)
await page.keyboard.press('Enter'); await page.waitForTimeout(200)
await page.keyboard.press('ArrowDown'); await page.waitForTimeout(150)
await page.keyboard.press('Enter'); await page.waitForTimeout(3700)
await page.keyboard.down('ArrowUp')
let held = { left: false, right: false, drift: false }
const set = async (name, want) => {
  if (held[name] === want) return
  held[name] = want
  const key = name === 'drift' ? ' ' : name === 'left' ? 'ArrowLeft' : 'ArrowRight'
  if (want) await page.keyboard.down(key); else await page.keyboard.up(key)
}
let samples = []
for (let step = 0; step < 420; step++) {
  const s = await page.evaluate(() => {
    const g = window.__NEON_APEX__; const d = g.drift; const w = g.driftWorld
    if (!d || d.phase !== 'run') return { phase: d?.phase }
    let best = 1e9, bi = 0
    for (let i = 0; i < w.samples.length; i++) {
      const dx = d.car.x - w.samples[i].x, dy = d.car.y - w.samples[i].y
      const dd = dx * dx + dy * dy
      if (dd < best) { best = dd; bi = i }
    }
    const ahead = w.samples[(bi + 10) % w.samples.length]
    const dx = ahead.x - d.car.x, dy = ahead.y - d.car.y
    const desired = Math.atan2(dy, dx)
    let diff = desired - d.car.angle
    while (diff > Math.PI) diff -= Math.PI * 2
    while (diff < -Math.PI) diff += Math.PI * 2
    return { phase: d.phase, timer: d.timer, x: d.car.x, y: d.car.y, angle: d.car.angle, speed: d.car.speed, slip: d.car.slip, score: d.scoreF, combo: d.combo, walls: d.walls, bestCombo: d.bestCombo, diff, dist: Math.sqrt(best), bi }
  })
  if (s.phase !== 'run') break
  if (step % 15 === 0) samples.push({ ...s, diff: +(s.diff * 180 / Math.PI).toFixed(0) })
  if (Math.abs(s.diff) > 0.12) {
    await set('left', s.diff < 0)
    await set('right', s.diff > 0)
  } else { await set('left', false); await set('right', false) }
  const wantDrift = s.speed > 150 && step % 90 > 25 && step % 90 < 80
  await set('drift', wantDrift)
  await page.waitForTimeout(60)
}
await set('left', false); await set('right', false); await set('drift', false); await page.keyboard.up('ArrowUp')
await page.waitForTimeout(300)
console.log(samples)
console.log('final', await page.evaluate(() => { const A = window.__NEON_APEX__; const d = A.game.drift; return { phase: d.phase, timer: d.timer, score: d.scoreF, combo: d.combo, walls: d.walls, bestCombo: d.bestCombo, speed: d.car.speed, result: d.result } }))
await page.screenshot({ path: '/tmp/opencode/d-autopilot.png' })
console.log('errors', errors)
await browser.close()

