input.content:
import { createRequire } from 'node:module'
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json')
const { chromium } = require('playwright')
const browser = await chromium.launch({ args: ['--use-gl=swiftshader'] })
const context = await browser.newContext({ viewport: { width: 390, height: 844 }, screen: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 })
const page = await context.newPage()
const errors = []
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()) })
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message))
await page.goto('http://localhost:3002/', { waitUntil: 'load' })
await page.evaluate(() => {
  localStorage.clear()
  localStorage.setItem('neon-apex-save-v1', JSON.stringify({ cash: 5000, owned: ['vulcan'], selected: 'vulcan', bestDrag: null, bestDrift: 0, muted: false, runs: 0 }))
})
await page.reload({ waitUntil: 'load' })
await page.waitForTimeout(400)
const info = () => page.evaluate(() => {
  const A = window.__NEON_APEX__
  return { screen: A.game.screen, paused: A.game.paused, save: { ...A.save }, drag: A.game.drag && { phase: A.game.drag.phase, rpm: A.game.drag.player.rpm, gear: A.game.drag.player.gear, dist: A.game.drag.player.distance, result: A.game.drag.result }, drift: A.game.drift && { phase: A.game.drift.phase, timer: A.game.drift.timer, result: A.game.drift.result }, body: document.body.className, hits: A.game.hits.map(h => h.id), cashText: document.getElementById('muteBtn').textContent }
})
const box = await page.locator('#frame').boundingBox()
const tapV = async (x, y) => { await page.touchscreen.tap(box.x + x * box.width / 384, box.y + y * box.height / 216); await page.waitForTimeout(350) }
// title -> menu -> garage
await page.touchscreen.tap(195, 422); await page.waitForTimeout(400)
console.log('menu', await info())
await tapV(100, 148)
console.log('garage vulcan', await info())
await page.screenshot({ path: '/tmp/opencode/m3-garage.png' })
// right to komet then buy
await tapV(235, 119)
console.log('garage komet', await info())
await tapV(192, 190)
console.log('buy komet', await info())
await page.screenshot({ path: '/tmp/opencode/m3-garage-buy.png' })
// back
await tapV(42, 190)
console.log('back menu', await info())
// drag
await tapV(100, 58)
await page.waitForTimeout(200)
console.log('drag count', await info())
await page.screenshot({ path: '/tmp/opencode/m3-drag-count.png' })
await page.waitForTimeout(2200)
// set up touch gas + shift/nitro
const gas = await page.locator('[data-act="throttle"]').boundingBox()
const shift = await page.locator('[data-act="shift"]').boundingBox()
const nitro = await page.locator('[data-act="nitro"]').boundingBox()
const pauseBtn = await page.locator('#pauseBtn').boundingBox()
const muteBtn = await page.locator('#muteBtn').boundingBox()
console.log('buttons', { gas, shift, nitro, pauseBtn, muteBtn })
const cdp = await context.newCDPSession(page)
const pt = (b, id) => ({ x: b.x + b.width / 2, y: b.y + b.height / 2, id, radiusX: 4, radiusY: 4, force: 1 })
const g = pt(gas, 1)
const s = pt(shift, 2)
const n = pt(nitro, 3)
const dispatch = (type, points) => cdp.send('Input.dispatchTouchEvent', { type, touchPoints: points })
await dispatch('touchStart', [g])
await page.waitForTimeout(1700)
console.log('gas held', await info())
let shifted = 0
for (let i = 0; i < 180; i++) {
  const st = await page.evaluate(() => { const A = window.__NEON_APEX__; const d = A.game.drag; return { phase: d.phase, rpm: d.player.rpm, gear: d.player.gear } })
  if (st.phase === 'done') break
  if (st.rpm > 6750 && st.gear < 5) {
    await dispatch('touchStart', [g, s])
    await page.waitForTimeout(35)
    await dispatch('touchEnd', [g])
    shifted++
  }
  if (i === 20) { await dispatch('touchStart', [g, n]); await page.waitForTimeout(40); await dispatch('touchEnd', [g]) }
  await page.waitForTimeout(30)
}
console.log('shifts', shifted, await info())
await page.screenshot({ path: '/tmp/opencode/m3-drag-finish.png' })
await page.waitForTimeout(1000)
console.log('drag done', await info())
await page.screenshot({ path: '/tmp/opencode/m3-drag-result.png' })
// release gas and tap retry at 132,173
await dispatch('touchEnd', [])
await page.waitForTimeout(200)
await tapV(132, 173)
console.log('retry', await info())
// pause button touch
await page.touchscreen.tap(pauseBtn.x + 10, pauseBtn.y + 10); await page.waitForTimeout(400)
console.log('paused', await info())
await page.screenshot({ path: '/tmp/opencode/m3-pause.png' })
// resume via canvas 192,106
await tapV(192, 106)
console.log('resumed', await info())
// mute
await page.touchscreen.tap(muteBtn.x + 10, muteBtn.y + 10); await page.waitForTimeout(300)
console.log('muted', await page.evaluate(() => ({ muted: window.__NEON_APEX__.save.muted, label: document.getElementById('muteBtn').textContent })))
// quit via pause then click quit 192,134
await page.touchscreen.tap(pauseBtn.x + 10, pauseBtn.y + 10); await page.waitForTimeout(300)
await tapV(192, 134)
console.log('quit', await info())
console.log('errors', errors)
await browser.close()

